import { UpdateUserDto } from './dto/update-user.dto';
import { UserResponseDto } from './dto/user-response.dto';
import {
  CompleteProfileImageUploadDto,
  ProfileImageResponseDto,
  ProfileImageUploadUrlDto,
} from './dto/profile-image-upload.dto';
import { ProfileImagesService } from './profile-images.service';
import { swagger } from './swagger.config';
import { UsersService } from './users.service';

@ApiTags('Users')
@ApiBearerAuth()
@ApiUnauthorizedResponse({ description: 'Missing or invalid access token' })
@Controller('users')
export class UsersController {
  constructor(
    private readonly usersService: UsersService,
    private readonly profileImagesService: ProfileImagesService,
  ) {}

  @Post('me/profile-image/upload-url')
  @Roles(Role.INSTRUCTOR, Role.INSTITUTION)
  @swagger.profileImageUploadUrl()
  @ResponseMessage('Profile image upload URL created successfully')
  createProfileImageUploadUrl(@CurrentUser() user: AuthUser, @Body() dto: ProfileImageUploadUrlDto) {
    return this.profileImagesService.createUploadUrl(user, dto);
  }

  @Post('me/profile-image/upload-complete')
  @Roles(Role.INSTRUCTOR, Role.INSTITUTION)
  @swagger.profileImageUploadComplete()
  @ResponseMessage('Profile image updated successfully')
  completeProfileImageUpload(
    @CurrentUser() user: AuthUser,
    @Body() dto: CompleteProfileImageUploadDto,
  ): Promise<ProfileImageResponseDto> {
    return this.profileImagesService.completeUpload(user, dto);
  }

  @Get('me/profile-image')
  @Roles(Role.INSTRUCTOR, Role.INSTITUTION)
  @swagger.profileImageGet()
  @ResponseMessage('Profile image fetched successfully')
  getProfileImage(@CurrentUser() user: AuthUser): Promise<ProfileImageResponseDto> {
    return this.profileImagesService.getImage(user);
  }

  @Post('admin')
  @Roles(Role.ADMIN)
  @swagger.adminCreate()
  @ResponseMessage('User created successfully')
  async adminCreate(@Body() dto: AdminCreateUserDto) {
    return UserResponseDto.fromUser(await this.usersService.createByAdmin(dto));
  }

  @Get()
  @Roles(Role.ADMIN)
  @swagger.findAll()
  @ResponseMessage('Users fetched successfully')
  async findAll(@Query() query: ListUsersQueryDto) {
    const result = await this.usersService.findAll(query);

    return {
      users: result.users.map((user) => AdminUserResponseDto.fromUser(user)),
      pagination: result.pagination,
    };
  }

  @Get(':id')
  @swagger.getById()
  @ResponseMessage('User fetched successfully')
  async getById(@Param('id') id: string) {
    const user = await this.usersService.getById(id);

    return UserResponseDto.fromUser(user);
  }

  @Patch('me')
  @swagger.update()
  @ResponseMessage('User updated successfully')
  async update(@CurrentUser('id') userId: string, @Body() updateUserDto: UpdateUserDto) {
    const user = await this.usersService.update(userId, updateUserDto);

    return UserResponseDto.fromUser(user);
  }

  @Patch('admin/:id')
  @Roles(Role.ADMIN)
  @swagger.adminUpdate()
  @ResponseMessage('User updated successfully')
  async adminUpdate(@Param('id', new ParseUUIDPipe()) id: string, @Body() updateUserDto: AdminUpdateUserDto) {
    const user = await this.usersService.update(id, updateUserDto);

    return UserResponseDto.fromUser(user);
  }

