import { BadRequestException, ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { AdminCreateUserDto } from './dto/admin-create-user.dto';
import { Prisma } from '@prisma/client';
import { PRISMA_ERROR_CODE } from '../../common/constants/prisma-error.constants';
import { Role } from '../../common/enums/role.enum';
import { ListUsersQueryDto } from './dto/list-users-query.dto';
import { CreateUserInput, UpdateUserInput, UsersRepository } from './users.repository';

@Injectable()
export class UsersService {
  constructor(private readonly usersRepository: UsersRepository) {}

  create(data: CreateUserInput) {
    return this.usersRepository.create(data);
  }

  async createByAdmin(dto: AdminCreateUserDto) {
    const phone = dto.phone?.trim();
    if (dto.phoneVerified && !phone) {
      throw new BadRequestException('A phone number is required before it can be verified');
    }

    const password = await bcrypt.hash(dto.password, 10);
    try {
      return await this.usersRepository.create({
        email: dto.email,
        role: dto.role,
        password,
        name: dto.name?.trim(),
        phone,
        emailVerified: dto.emailVerified ?? false,
        phoneVerified: dto.phoneVerified ?? false,
      });
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === PRISMA_ERROR_CODE.UNIQUE_CONSTRAINT) {
        throw new ConflictException('Email is already registered');
      }
      throw error;
    }
  }

  recordLogin(id: string) {
    return this.usersRepository.update(id, { lastLogin: new Date() });
  }

  findById(id: string) {
    return this.usersRepository.findById(id);
  }

  findManyByIds(ids: string[]) {
    return this.usersRepository.findManyByIds(ids);
  }

  findByEmail(email: string) {
    return this.usersRepository.findByEmail(email);
  }

  findByEmailWithPassword(email: string) {
    return this.usersRepository.findByEmailWithPassword(email);
  }

  async findAll(query: ListUsersQueryDto) {
    if (query.status && query.profileStatus && query.status !== query.profileStatus) {
      throw new BadRequestException('status and profileStatus must match when both are provided');
    }
    if (query.joined && (query.createdFrom || query.createdTo)) {
      throw new BadRequestException('Use joined or createdFrom/createdTo, not both');
    }
    const from = query.joined ?? query.createdFrom;
    const to = query.joined ?? query.createdTo;
    const createdFrom = from ? new Date(from) : undefined;
    const createdTo = to ? new Date(to) : undefined;
    if (to && createdTo && /^\d{4}-\d{2}-\d{2}$/.test(to)) createdTo.setUTCHours(23, 59, 59, 999);
    if (createdFrom && createdTo && createdFrom > createdTo) {
      throw new BadRequestException('createdFrom must be on or before createdTo');
    }

    const search = query.search?.trim() || undefined;
    const [users, total] = await this.usersRepository.findManyAndCount({
      skip: (query.page - 1) * query.limit,
      take: query.limit,
      search,
      role: query.role,
      accountType: query.accountType,
      countries: query.countries,
      emailVerified: query.emailVerified,
      phoneVerified: query.phoneVerified,
      profileStatus: query.profileStatus ?? query.status,
      createdFrom,
      createdTo,
      sortBy: query.sortBy === 'lastLogin' ? 'lastLogin' : 'createdAt',
      sortOrder: query.sortOrder ?? 'desc',
    });
    const totalPages = Math.ceil(total / query.limit);

    return {
      users,
      pagination: {
        page: query.page,
        limit: query.limit,
        total,
        totalPages,
        hasNextPage: query.page < totalPages,
      },
    };
  }

  async getById(id: string) {
    const user = await this.findById(id);

    if (!user) {
      throw new NotFoundException('User not found');
    }

    return { ...user, twoFactorEnabled: Boolean(user.twoFactorAuth?.enabledAt) };
  }

  async update(id: string, updateUserInput: UpdateUserInput) {
    const current = await this.getById(id);
    const phone = updateUserInput.phone === undefined ? current.phone : updateUserInput.phone;
    if (updateUserInput.phoneVerified && !phone?.trim()) {
      throw new BadRequestException('A phone number is required before it can be verified');
    }

    // A profile belongs to the role it was created under; changing the role would orphan it.
    if (updateUserInput.role && updateUserInput.role !== current.role && (await this.usersRepository.hasProfile(id))) {
      throw new ConflictException('The user has a profile; delete it before changing their role');
    }

    const data: UpdateUserInput = {
      name: updateUserInput.name,
      role: updateUserInput.role,
      phone: updateUserInput.phone,
      emailVerified: updateUserInput.emailVerified,
      phoneVerified:
        updateUserInput.phoneVerified ??
        (updateUserInput.phone !== undefined && updateUserInput.phone !== current.phone ? false : undefined),
    };

    return this.usersRepository.update(id, data);
  }

  async remove(id: string): Promise<void> {
    try {
      await this.usersRepository.remove(id);
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        if (error.code === PRISMA_ERROR_CODE.RECORD_NOT_FOUND) {
          throw new NotFoundException('User not found');
        }

        if (error.code === PRISMA_ERROR_CODE.FOREIGN_KEY_CONSTRAINT) {
          throw new ConflictException('User has related records and cannot be deleted');
        }
      }

      throw error;
    }
  }

  async markEmailVerified(id: string) {
    await this.getById(id);

    return this.usersRepository.update(id, {
      emailVerified: true,
    });
  }

  async markPhoneVerified(id: string, phone: string) {
    await this.getById(id);

    return this.usersRepository.update(id, {
      phone,
      phoneVerified: true,
    });
  }

  async updatePassword(id: string, password: string) {
    await this.getById(id);

    return this.usersRepository.updatePassword(id, password);
  }

  /** Re-registration of an unverified account: the new password and role replace the old ones. */
  async updateSignup(id: string, password: string, role: Role) {
    await this.getById(id);

    return this.usersRepository.updateSignup(id, password, role);
  }
}

