import { Injectable } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { ProfileStatus } from '../../common/enums/profile-status.enum';
import { Role } from '../../common/enums/role.enum';
import { PrismaService } from '../../prisma/prisma.service';

export type UserRecord = {
  id: string;
  email: string;
  name?: string | null;
  role: Role;
  emailVerified?: boolean;
  phoneVerified?: boolean;
  phone?: string | null;
  lastLogin?: Date | null;
  createdAt?: Date;
  updatedAt?: Date;
  twoFactorAuth?: { enabledAt: Date | null } | null;
  instructorProfile?: { countryCode: string; status: ProfileStatus } | null;
  institutionProfile?: { countryCode: string; status: ProfileStatus } | null;
};

export type UserWithPasswordRecord = UserRecord & {
  password: string | null;
};

export type CreateUserInput = {
  email: string;
  role: Role;
  password?: string | null;
  name?: string;
  phone?: string;
  emailVerified?: boolean;
  phoneVerified?: boolean;
};

export type UpdateUserInput = {
  name?: string;
  role?: Role;
  phone?: string | null;
  emailVerified?: boolean;
  phoneVerified?: boolean;
  lastLogin?: Date;
};

export type ListUsersInput = {
  skip: number;
  take: number;
  search?: string;
  role?: Role;
  accountType?: 'ADMIN' | 'USERS';
  countries?: string[];
  emailVerified?: boolean;
  phoneVerified?: boolean;
  profileStatus?: ProfileStatus;
  createdFrom?: Date;
  createdTo?: Date;
  sortBy?: 'createdAt' | 'lastLogin';
  sortOrder?: 'asc' | 'desc';
};

type PrismaUserDelegate = {
  findUnique(args: unknown): Promise<UserRecord | null>;
  findMany(args: unknown): Promise<UserRecord[]>;
  count(args: unknown): Promise<number>;
  create(args: unknown): Promise<UserRecord>;
  update(args: unknown): Promise<UserRecord>;
  delete(args: unknown): Promise<UserRecord>;
};

@Injectable()
export class UsersRepository {
  constructor(private readonly prisma: PrismaService) {}

  /** Just enough to re-check who may still hold a live connection. */
  findManyByIds(ids: string[]) {
    return this.users.findMany({ where: { id: { in: ids } }, select: { id: true, role: true } });
  }

