import { BadRequestException, ConflictException, HttpException, HttpStatus, Injectable } from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { generateOtp, otpMaxAttempts, otpTtlMinutes } from '../../common/otp/otp-policy';
import { toE164 } from '../sms/phone-number';
import { SmsService } from '../sms/sms.service';
import { UserResponseDto } from '../users/dto/user-response.dto';
import { UsersService } from '../users/users.service';
import { PhoneOtpResponseDto } from './dto/phone-verification.dto';
import { PhoneVerificationOtpRepository } from './phone-verification-otp.repository';

const HOUR_MS = 60 * 60 * 1000;

@Injectable()
export class PhoneVerificationService {
  constructor(
    private readonly usersService: UsersService,
    private readonly otpRepository: PhoneVerificationOtpRepository,
    private readonly smsService: SmsService,
  ) {}

  async sendOtp(userId: string, rawPhone: string): Promise<PhoneOtpResponseDto> {
    const phone = toE164(rawPhone);

    if (!phone) {
      throw new BadRequestException('phone must be a valid phone number');
    }

    const user = await this.usersService.getById(userId);

    if (user.phoneVerified && user.phone === phone) {
      throw new ConflictException('This phone number is already verified');
    }

    // Every SMS costs money and is a target for SMS-pumping fraud, so sends are throttled per user.
    await this.assertCanSend(userId);

    const otp = generateOtp();
    const expiresInMinutes = otpTtlMinutes();

    await this.otpRepository.create({
      userId,
      phone,
      codeHash: await bcrypt.hash(otp, 10),
      expiresAt: new Date(Date.now() + expiresInMinutes * 60 * 1000),
    });
    await this.smsService.sendPhoneVerificationOtp(phone, otp, expiresInMinutes);

    return {
      phone,
      expiresInMinutes,
      resendAvailableInSeconds: this.resendCooldownSeconds,
    };
  }

  async verifyOtp(userId: string, otp: string): Promise<UserResponseDto> {
    const otpRecord = await this.otpRepository.findLatestActiveByUserId(userId);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      const updatedOtp = await this.otpRepository.incrementAttempts(otpRecord.id);

      if (updatedOtp.attempts >= otpMaxAttempts()) {
        await this.otpRepository.consume(otpRecord.id);
      }

      throw new BadRequestException('Invalid or expired verification code');
    }

    await this.otpRepository.consumeAllForUser(userId);
    // The code proves ownership of the number it was sent to, so that number becomes the user's phone.
    await this.usersService.markPhoneVerified(userId, otpRecord.phone);

    return UserResponseDto.fromUser(await this.usersService.getById(userId));
  }

  private async assertCanSend(userId: string) {
    const latest = await this.otpRepository.findLatestByUserId(userId);

    if (latest) {
      const waitSeconds = Math.ceil(
        (latest.createdAt.getTime() + this.resendCooldownSeconds * 1000 - Date.now()) / 1000,
      );

      if (waitSeconds > 0) {
        throw new HttpException(
          `Please wait ${waitSeconds} seconds before requesting another code`,
          HttpStatus.TOO_MANY_REQUESTS,
        );
      }
    }

    const sentLastHour = await this.otpRepository.countSentSince(userId, new Date(Date.now() - HOUR_MS));

    if (sentLastHour >= this.maxSendsPerHour) {
      throw new HttpException('Too many verification codes requested; try again later', HttpStatus.TOO_MANY_REQUESTS);
    }
  }

  private get resendCooldownSeconds() {
    const configured = Number(process.env.PHONE_OTP_RESEND_COOLDOWN_SECONDS);

    return Number.isInteger(configured) && configured >= 0 ? configured : 60;
  }

  private get maxSendsPerHour() {
    const configured = Number(process.env.PHONE_OTP_MAX_SENDS_PER_HOUR);

    return Number.isInteger(configured) && configured > 0 ? configured : 5;
  }
}

