export class PhoneVerificationService {
  constructor(
    private readonly usersService: UsersService,
    private readonly otpRepository: PhoneVerificationOtpRepository,
    private readonly smsService: SmsService,
  ) {}

  async sendOtp(userId: string, rawPhone: string): Promise<PhoneOtpResponseDto> {
    const phone = toE164(rawPhone);

    if (!phone) {
      throw new BadRequestException('phone must be a valid phone number');
    }

    const user = await this.usersService.getById(userId);

    if (user.phoneVerified) {
      throw new ConflictException({
        code: 'PHONE_VERIFIED_LOCKED',
        message: 'This number is verified and cannot be edited.',
      });
    }

    const otp = generateOtp();
    const expiresInMinutes = otpTtlMinutes();

    await this.otpRepository.create(
      {
        userId,
        phone,
        codeHash: await bcrypt.hash(otp, 10),
        expiresAt: new Date(Date.now() + expiresInMinutes * 60 * 1000),
      },
      { cooldownSeconds: this.resendCooldownSeconds, maxPerHour: this.maxSendsPerHour },
    );
    await this.smsService.sendPhoneVerificationOtp(phone, otp, expiresInMinutes);

    return {
      phone,
      expiresInMinutes,
      resendAvailableInSeconds: this.resendCooldownSeconds,
    };
  }

  async verifyOtp(userId: string, otp: string): Promise<UserResponseDto> {
    const otpRecord = await this.otpRepository.findLatestActiveByUserId(userId);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      await this.otpRepository.recordFailedAttempt(otpRecord.id, userId, otpMaxAttempts());

      throw new BadRequestException('Invalid or expired verification code');
    }

    const completed = await this.otpRepository.complete(
      otpRecord.id,
      userId,
      otpMaxAttempts(),
      otpRecord.phone,
    );
    if (!completed) throw new BadRequestException('Invalid or expired verification code');

    return UserResponseDto.fromUser(await this.usersService.getById(userId));
  }

  private get resendCooldownSeconds() {
    const configured = Number(process.env.PHONE_OTP_RESEND_COOLDOWN_SECONDS);

    return Number.isInteger(configured) && configured >= 0 ? configured : 60;
  }

  private get maxSendsPerHour() {
    const configured = Number(process.env.PHONE_OTP_MAX_SENDS_PER_HOUR);

    return Number.isInteger(configured) && configured > 0 ? configured : 5;
  }
}

