};

type EmailVerificationOtpDelegate = {
  create(args: unknown): Promise<EmailVerificationOtpRecord>;
  findFirst(args: unknown): Promise<EmailVerificationOtpRecord | null>;
  update(args: unknown): Promise<EmailVerificationOtpRecord>;
  updateMany(args: unknown): Promise<{ count: number }>;
