@Injectable()
export class EmailVerificationOtpRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: { userId: string; codeHash: string; expiresAt: Date }) {
    const now = new Date();

    await this.otps.updateMany({
      where: {
        userId: data.userId,
        consumedAt: null,
      },
      data: {
        consumedAt: now,
      },
    });

    return this.otps.create({
