import { PrismaService } from '../../prisma/prisma.service';
import { assertOtpSendAllowed, otpSendLimit } from '../../common/otp/otp-send-limit';
import { Role } from '../../common/enums/role.enum';

@Injectable()
export class EmailVerificationOtpRepository {
  constructor(private readonly prisma: PrismaService) {}

  async create(data: {
    userId: string;
    codeHash: string;
    expiresAt: Date;
    signup?: { password: string; role: Role };
  }) {
    return this.prisma.$transaction(async (transaction) => {
      // All OTP send/verify transactions lock the same user row before changing a code.
      await transaction.$queryRaw`SELECT "id" FROM "User" WHERE "id" = ${data.userId} FOR UPDATE`;
      const user = await transaction.user.findUnique({ where: { id: data.userId } });
      if (!user) throw new BadRequestException('Unable to send verification code');
      if (user.emailVerified) throw new ConflictException('Email is already verified');
      const now = new Date();
      const latest = await transaction.emailVerificationOtp.findFirst({
        where: { userId: data.userId },
        orderBy: { createdAt: 'desc' },
      });
      const count = await transaction.emailVerificationOtp.count({
        where: { userId: data.userId, createdAt: { gte: new Date(now.getTime() - 60 * 60 * 1000) } },
      });
      assertOtpSendAllowed(latest, count, otpSendLimit(), now);
      const { signup, ...record } = data;
      if (signup) await transaction.user.update({ where: { id: data.userId }, data: signup });
      await transaction.emailVerificationOtp.updateMany({
        where: { userId: data.userId, consumedAt: null },
        data: { consumedAt: now },
      });
      return transaction.emailVerificationOtp.create({ data: record });
    });
  }

  findLatestActiveByUserId(userId: string, now = new Date()) {
    return this.prisma.emailVerificationOtp.findFirst({
      where: { userId, consumedAt: null, expiresAt: { gt: now } },
      orderBy: { createdAt: 'desc' },
    });
  }

  recordFailedAttempt(id: string, userId: string, maxAttempts: number) {
    return this.prisma.emailVerificationOtp.updateMany({
      where: { id, userId, consumedAt: null, expiresAt: { gt: new Date() }, attempts: { lt: maxAttempts } },
      data: { attempts: { increment: 1 } },
    });
  }

  async complete(id: string, userId: string, maxAttempts: number): Promise<boolean> {
    return this.prisma.$transaction(async (transaction) => {
      await transaction.$queryRaw`SELECT "id" FROM "User" WHERE "id" = ${userId} FOR UPDATE`;
      const user = await transaction.user.findUnique({ where: { id: userId } });
      if (!user || user.emailVerified) return false;
