import { BadRequestException, ConflictException, Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService, type JwtSignOptions } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { randomUUID } from 'node:crypto';
import { Role, type SignupRole } from '../../common/enums/role.enum';
import { generateOtp, otpMaxAttempts, otpTtlMinutes } from '../../common/otp/otp-policy';
import { UsersService } from '../users/users.service';
import { UserResponseDto } from '../users/dto/user-response.dto';
import { EmailVerificationOtpRepository } from './email-verification-otp.repository';
import { LoginDto } from './dto/login.dto';
import { PasswordResetOtpRepository } from './password-reset-otp.repository';
import { RegisterDto } from './dto/register.dto';
import {
  AUTH_TOKEN_TYPE,
  AuthTokenPayload,
  OTP_TOKEN_PURPOSE,
  OtpTokenPurpose,
  otpTokenSecret,
} from './auth-token.constants';
import { EmailService } from '../email/email.service';
import { GoogleOAuthService } from '../google-oauth/google-oauth.service';
import { TwoFactorService } from '../two-factor/two-factor.service';

type AuthenticatedResponse = {
  user: UserResponseDto;
  accessToken: string;
  refreshToken: string;
  accessTokenExpiresAt: string;
  accessTokenExpiresInSeconds: number;
  refreshTokenExpiresAt: string;
  refreshTokenExpiresInSeconds: number;
};

type DecodedTokenExpiry = {
  exp?: number;
};

type TwoFactorChallengeResponse = {
  twoFactorRequired: true;
  twoFactorToken: string;
  expiresInMinutes: number;
};

@Injectable()
export class AuthService {
  private readonly refreshSecret =
    process.env.JWT_REFRESH_SECRET ?? `${process.env.JWT_SECRET ?? 'change-me-in-env'}-refresh`;

  constructor(
    private readonly usersService: UsersService,
    private readonly jwtService: JwtService,
    private readonly emailOtpRepository: EmailVerificationOtpRepository,
    private readonly passwordResetOtpRepository: PasswordResetOtpRepository,
    private readonly mailService: EmailService,
    private readonly googleOAuthService: GoogleOAuthService,
    private readonly twoFactorService: TwoFactorService,
  ) {}

  async register(registerDto: RegisterDto) {
    const existingUser = await this.usersService.findByEmail(registerDto.email);

    if (existingUser && existingUser.emailVerified) {
      throw new ConflictException('Email is already registered');
    }
    const hashedPassword = await bcrypt.hash(registerDto.password, 10);

    if (existingUser && !existingUser.emailVerified) {
      const user = await this.usersService.updateSignup(existingUser.id, hashedPassword, registerDto.role);
      await this.issueEmailVerificationOtp(user);
      return this.createEmailVerificationResponse(user);
    }

    const user = await this.usersService.create({
      email: registerDto.email,
      password: hashedPassword,
      role: registerDto.role,
    });
    await this.issueEmailVerificationOtp(user);

    return this.createEmailVerificationResponse(user);
  }

  async login(loginDto: LoginDto) {
    const user = await this.usersService.findByEmailWithPassword(loginDto.email);
    if (!user || !user.password) {
      throw new UnauthorizedException('Invalid email or password');
    }

    const passwordMatches = await bcrypt.compare(loginDto.password, user.password);

    if (!passwordMatches) {
      throw new UnauthorizedException('Invalid email or password');
    }

    if (!user.emailVerified) {
      await this.issueEmailVerificationOtp(user);
      return this.createEmailVerificationResponse(user);
    }

    return this.createAuthenticatedResponse(user);
  }

  async loginWithGoogle(credential: string, role?: SignupRole) {
    const user = await this.googleOAuthService.authenticate(credential, role);

    return this.createAuthenticatedResponse(user);
  }

  async refresh(refreshToken: string) {
    if (!refreshToken) {
      throw new BadRequestException('refreshToken is required');
    }

    try {
      const payload = await this.jwtService.verifyAsync<AuthTokenPayload>(refreshToken, {
        secret: this.refreshSecret,
      });
      const user = await this.usersService.findById(payload.sub);

      if (payload.tokenType !== AUTH_TOKEN_TYPE.REFRESH || !user?.emailVerified) {
        throw new UnauthorizedException('Invalid refresh token');
      }

      const twoFactorEnabled = await this.twoFactorService.isEnabled(user.id);

      if (twoFactorEnabled && payload.twoFactorVerified !== true) {
        throw new UnauthorizedException('Invalid refresh token');
      }

      return {
        user: UserResponseDto.fromUser({ ...user, twoFactorEnabled }),
        ...(await this.signTokens(user, payload.twoFactorVerified === true)),
      };
    } catch {
      throw new UnauthorizedException('Invalid refresh token');
    }
  }

  async me(userId: string) {
    const user = await this.usersService.getById(userId);

    return UserResponseDto.fromUser({ ...user, twoFactorEnabled: await this.twoFactorService.isEnabled(user.id) });
  }

  async verifyTwoFactorLogin(userId: string, challengeId: string | undefined, code: string) {
    await this.twoFactorService.verifyLoginChallenge(userId, challengeId, code);
    const user = await this.usersService.getById(userId);

    return this.createLoginResponse(user, true);
  }

  async resendEmailVerificationOtp(email: string) {
    const user = await this.usersService.findByEmail(email);

    if (!user) {
      throw new BadRequestException('Unable to send verification email');
    }

    if (user.emailVerified) {
      return {
        emailVerified: true,
        expiresInMinutes: 0,
      };
    }

    await this.issueEmailVerificationOtp(user);

    return {
      emailVerified: false,
      expiresInMinutes: otpTtlMinutes(),
      otpToken: await this.signOtpToken(user, OTP_TOKEN_PURPOSE.EMAIL_VERIFICATION, otpTtlMinutes()),
    };
  }

  async verifyEmailOtp(userId: string, otp: string) {
    const user = await this.usersService.findById(userId);

    if (!user) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    if (user.emailVerified) {
      throw new BadRequestException('Email is already verified');
    }

    const otpRecord = await this.emailOtpRepository.findLatestActiveByUserId(user.id);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired verification code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      const updatedOtp = await this.emailOtpRepository.incrementAttempts(otpRecord.id);

      if (updatedOtp.attempts >= otpMaxAttempts()) {
        await this.emailOtpRepository.consume(otpRecord.id);
      }

      throw new BadRequestException('Invalid or expired verification code');
    }

    await this.emailOtpRepository.consumeAllForUser(user.id);
    const verifiedUser = await this.usersService.markEmailVerified(user.id);

    return this.createLoginResponse(verifiedUser);
  }

  async forgotPassword(email: string) {
    const user = await this.usersService.findByEmail(email);
    if (user) {
      await this.issuePasswordResetOtp(user);
    }

    return {
      expiresInMinutes: otpTtlMinutes(),
      otpToken: await this.signOtpToken(
        {
          id: user?.id ?? randomUUID(),
          email,
          // Unknown emails get a decoy token so the response never reveals whether an account exists.
          role: user?.role ?? Role.INSTRUCTOR,
        },
        OTP_TOKEN_PURPOSE.PASSWORD_RESET,
        otpTtlMinutes(),
      ),
    };
  }

  async resetPassword(userId: string, otp: string, password: string) {
    const user = await this.usersService.findById(userId);

    if (!user) {
      throw new BadRequestException('Invalid or expired password reset code');
    }

    const otpRecord = await this.passwordResetOtpRepository.findLatestActiveByUserId(user.id);

    if (!otpRecord || otpRecord.attempts >= otpMaxAttempts()) {
      throw new BadRequestException('Invalid or expired password reset code');
    }

    const otpMatches = await bcrypt.compare(otp, otpRecord.codeHash);

    if (!otpMatches) {
      const updatedOtp = await this.passwordResetOtpRepository.incrementAttempts(otpRecord.id);

      if (updatedOtp.attempts >= otpMaxAttempts()) {
        await this.passwordResetOtpRepository.consume(otpRecord.id);
      }

      throw new BadRequestException('Invalid or expired password reset code');
    }

    const hashedPassword = await bcrypt.hash(password, 10);

    await this.usersService.updatePassword(user.id, hashedPassword);
    await this.passwordResetOtpRepository.consumeAllForUser(user.id);

    return {
      passwordReset: true,
    };
  }

  private async issueEmailVerificationOtp(user: { id: string; email: string; emailVerified?: boolean | null }) {
    if (user.emailVerified) {
      return;
    }

    const otp = generateOtp();
    const codeHash = await bcrypt.hash(otp, 10);
    const expiresAt = new Date(Date.now() + otpTtlMinutes() * 60 * 1000);

    await this.emailOtpRepository.create({
      userId: user.id,
      codeHash,
      expiresAt,
    });
    await this.mailService.sendEmailVerificationOtp(user.email, otp);
  }

  private async issuePasswordResetOtp(user: { id: string; email: string }) {
    const otp = generateOtp();
    const codeHash = await bcrypt.hash(otp, 10);
    const expiresAt = new Date(Date.now() + otpTtlMinutes() * 60 * 1000);

    await this.passwordResetOtpRepository.create({
      userId: user.id,
      codeHash,
      expiresAt,
    });
    await this.mailService.sendPasswordResetOtp(user.email, otp);
  }

  private async signTokens(user: { id: string; email: string; role: Role }, twoFactorVerified = false) {
    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      twoFactorVerified,
    };

    const [accessToken, refreshToken] = await Promise.all([
      this.jwtService.signAsync({
        ...payload,
        tokenType: AUTH_TOKEN_TYPE.ACCESS,
      } satisfies AuthTokenPayload),
      this.jwtService.signAsync(
        {
          ...payload,
          tokenType: AUTH_TOKEN_TYPE.REFRESH,
        } satisfies AuthTokenPayload,
        {
          secret: this.refreshSecret,
          expiresIn: (process.env.JWT_REFRESH_EXPIRES_IN ?? '7d') as JwtSignOptions['expiresIn'],
        },
      ),
    ]);

    const accessTokenExpiry = this.getTokenExpiry(accessToken);
    const refreshTokenExpiry = this.getTokenExpiry(refreshToken);

    return {
      accessToken,
      refreshToken,
      accessTokenExpiresAt: accessTokenExpiry.expiresAt,
      accessTokenExpiresInSeconds: accessTokenExpiry.expiresInSeconds,
      refreshTokenExpiresAt: refreshTokenExpiry.expiresAt,
      refreshTokenExpiresInSeconds: refreshTokenExpiry.expiresInSeconds,
    };
  }

  private getTokenExpiry(token: string) {
    const payload = this.jwtService.decode<DecodedTokenExpiry>(token);

    if (!payload?.exp) {
      throw new Error('Signed token is missing its expiration claim');
    }

    return {
      expiresAt: new Date(payload.exp * 1000).toISOString(),
      expiresInSeconds: Math.max(0, payload.exp - Math.floor(Date.now() / 1000)),
    };
  }

  private async createAuthenticatedResponse(user: {
    id: string;
    email: string;
    role: Role;
  }): Promise<AuthenticatedResponse | TwoFactorChallengeResponse> {
    if (await this.twoFactorService.isEnabled(user.id)) {
      const challenge = await this.twoFactorService.createLoginChallenge(user.id);

      return {
        twoFactorRequired: true,
        twoFactorToken: await this.signOtpToken(
          user,
          OTP_TOKEN_PURPOSE.TWO_FACTOR_LOGIN,
          challenge.expiresInMinutes,
          challenge.challengeId,
        ),
        expiresInMinutes: challenge.expiresInMinutes,
      };
    }

    return this.createLoginResponse(user);
  }

  private async createLoginResponse(user: { id: string; email: string; role: Role }, twoFactorVerified = false) {
    const tokens = await this.signTokens(user, twoFactorVerified);
    const updatedUser = await this.usersService.recordLogin(user.id);
    return {
      user: UserResponseDto.fromUser({
        ...updatedUser,
        twoFactorEnabled: await this.twoFactorService.isEnabled(user.id),
      }),
