  ): Promise<boolean> {
    return this.completeTransaction(async (transaction) => {
      await this.consumeChallenge(transaction, challengeId, userId, maxAttempts);
      const authentication = await transaction.twoFactorAuthentication.updateMany({
        where: {
          userId,
          enabledAt: { not: null },
          recoveryCodeHashes: { equals: expectedHashes, has: recoveryCodeHash },
        },
        data: { recoveryCodeHashes: remainingHashes },
      });

      if (authentication.count !== 1) {
        throw new TwoFactorCompletionConflictError();
      }
    });
  }

  async disableWithTotp(userId: string, step: number): Promise<boolean> {
    const result = await this.prisma.twoFactorAuthentication.deleteMany({
      where: {
        userId,
        enabledAt: { not: null },
        OR: [{ lastUsedStep: null }, { lastUsedStep: { lt: step } }],
      },
    });

    return result.count === 1;
  }

  async disableWithRecoveryCode(userId: string, recoveryCodeHash: string): Promise<boolean> {
    const result = await this.prisma.twoFactorAuthentication.deleteMany({
      where: {
        userId,
        enabledAt: { not: null },
        recoveryCodeHashes: { has: recoveryCodeHash },
      },
    });

    return result.count === 1;
  }

  async disableByAdmin(userId: string): Promise<boolean> {
    return this.prisma.$transaction(async (transaction) => {
      const deleted = await transaction.twoFactorAuthentication.deleteMany({
        where: { userId, enabledAt: { not: null } },
      });
      if (deleted.count === 1) {
        await transaction.twoFactorChallenge.deleteMany({ where: { userId } });
      }
      return deleted.count === 1;
    });
  }

  async replaceRecoveryCodesWithTotp(userId: string, step: number, hashes: string[]): Promise<boolean> {
    const result = await this.prisma.twoFactorAuthentication.updateMany({
      where: {
        userId,
        enabledAt: { not: null },
        OR: [{ lastUsedStep: null }, { lastUsedStep: { lt: step } }],
      },
      data: {
        lastUsedStep: step,
        recoveryCodeHashes: hashes,
      },
    });

    return result.count === 1;
  }

  async replaceRecoveryCodesWithRecoveryCode(
    userId: string,
    recoveryCodeHash: string,
    hashes: string[],
  ): Promise<boolean> {
    const result = await this.prisma.twoFactorAuthentication.updateMany({
      where: {
        userId,
        enabledAt: { not: null },
        recoveryCodeHashes: { has: recoveryCodeHash },
      },
      data: { recoveryCodeHashes: hashes },
    });

    return result.count === 1;
  }

  private async consumeChallenge(
    transaction: Prisma.TransactionClient,
    challengeId: string,
    userId: string,
    maxAttempts: number,
  ): Promise<void> {
    const challenge = await transaction.twoFactorChallenge.updateMany({
      where: {
        id: challengeId,
        userId,
        consumedAt: null,
        expiresAt: { gt: new Date() },
        attempts: { lt: maxAttempts },
      },
      data: { consumedAt: new Date() },
    });

    if (challenge.count !== 1) {
      throw new TwoFactorCompletionConflictError();
    }
  }

  private async completeTransaction(
    operation: (transaction: Prisma.TransactionClient) => Promise<void>,
  ): Promise<boolean> {
    try {
      await this.prisma.$transaction(operation);
      return true;
    } catch (error) {
      if (error instanceof TwoFactorCompletionConflictError) {
        return false;
      }

      throw error;
    }
  }
