import {
  BadRequestException,
  ConflictException,
  HttpException,
  HttpStatus,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { UsersService } from '../users/users.service';
import { TwoFactorCryptoService } from './two-factor-crypto.service';
import { TwoFactorRepository } from './two-factor.repository';

@Injectable()
export class TwoFactorService {
  constructor(
    private readonly repository: TwoFactorRepository,
    private readonly crypto: TwoFactorCryptoService,
    private readonly usersService: UsersService,
  ) {}

  async setup(userId: string) {
    const user = await this.usersService.getById(userId);
    const existing = await this.repository.findByUserId(userId);

    if (existing?.enabledAt) {
      throw new ConflictException('Two-factor authentication is already enabled');
    }

    const secret = this.crypto.generateSecret();
    const authentication = await this.repository.replacePendingSecret(userId, this.crypto.encryptSecret(secret));

    if (!authentication) {
      throw new ConflictException('Two-factor authentication is already enabled');
    }

    const otpAuthUri = this.crypto.buildOtpAuthUri(user.email, secret);

    return {
      secret,
      otpAuthUri,
      qrCodeDataUrl: await this.crypto.createQrCodeDataUrl(otpAuthUri),
    };
  }

  async enable(userId: string, code: string) {
    const authentication = await this.repository.findByUserId(userId);

    if (!authentication) {
      throw new BadRequestException('Start two-factor authentication setup first');
    }

    if (authentication.enabledAt) {
      throw new ConflictException('Two-factor authentication is already enabled');
    }

    const secret = this.crypto.decryptSecret(authentication.secretEncrypted);
    const step = this.crypto.findMatchingTotpStep(secret, code);

    if (step === null) {
      throw new BadRequestException('Invalid two-factor authentication code');
    }

    const recoveryCodes = this.crypto.generateRecoveryCodes();
    const enabled = await this.repository.enable(
      userId,
      step,
      recoveryCodes.map((recoveryCode) => this.crypto.hashRecoveryCode(recoveryCode)),
    );

    if (!enabled) {
      throw new ConflictException('Two-factor authentication setup has changed; start setup again');
    }

    return {
      enabled: true,
      recoveryCodes,
    };
  }

  async status(userId: string) {
    const authentication = await this.repository.findByUserId(userId);

    return {
      enabled: Boolean(authentication?.enabledAt),
      setupPending: Boolean(authentication && !authentication.enabledAt),
      recoveryCodesRemaining: authentication?.enabledAt ? authentication.recoveryCodeHashes.length : 0,
    };
  }

  async isEnabled(userId: string): Promise<boolean> {
    const authentication = await this.repository.findByUserId(userId);

    return Boolean(authentication?.enabledAt);
  }

  async createLoginChallenge(userId: string) {
    const expiresInMinutes = this.challengeTtlMinutes;
    const existing = await this.repository.findLatestUnexpiredChallenge(userId);

    if (existing && existing.attempts >= this.maxAttempts) {
      throw new HttpException(
        'Too many invalid two-factor authentication attempts; try again later',
        HttpStatus.TOO_MANY_REQUESTS,
      );
    }

    if (existing && !existing.consumedAt) {
      return {
        challengeId: existing.id,
        expiresInMinutes: Math.max(1, Math.ceil((existing.expiresAt.getTime() - Date.now()) / 60_000)),
      };
    }

    const challenge = await this.repository.createChallenge(
      userId,
      new Date(Date.now() + expiresInMinutes * 60 * 1000),
    );

    return {
      challengeId: challenge.id,
      expiresInMinutes,
    };
  }

  async verifyLoginChallenge(userId: string, challengeId: string | undefined, code: string): Promise<void> {
    if (!challengeId) {
      throw this.invalidCode();
    }

    const [authentication, challenge] = await Promise.all([
      this.repository.findByUserId(userId),
      this.repository.findActiveChallenge(challengeId, userId),
    ]);

    if (!authentication?.enabledAt || !challenge || challenge.attempts >= this.maxAttempts) {
      throw this.invalidCode();
    }

    const completed = await this.completeChallenge(authentication, challengeId, userId, code, this.maxAttempts);

    if (!completed) {
      const consume = challenge.attempts + 1 >= this.maxAttempts;
      await this.repository.recordFailedChallenge(
        challengeId,
        consume,
        consume ? new Date(Date.now() + this.challengeTtlMinutes * 60 * 1000) : undefined,
      );
      throw this.invalidCode();
    }
  }

  async disable(userId: string, code: string) {
    const authentication = await this.getEnabledAuthentication(userId);
    const disabled = this.crypto.isRecoveryCode(code)
      ? await this.repository.disableWithRecoveryCode(userId, this.crypto.hashRecoveryCode(code))
      : await this.disableWithTotp(userId, authentication.secretEncrypted, code);

    if (!disabled) {
      throw this.invalidCode();
    }

    return { enabled: false };
  }

  async disableByAdmin(adminId: string, userId: string) {
    if (adminId === userId) {
      throw new BadRequestException('Use a verification code to disable your own two-factor authentication');
    }
    await this.usersService.getById(userId);
    if (!(await this.repository.disableByAdmin(userId))) {
      throw new BadRequestException('Two-factor authentication is not enabled');
    }
    return { enabled: false };
  }

  async regenerateRecoveryCodes(userId: string, code: string) {
    const authentication = await this.getEnabledAuthentication(userId);
    const recoveryCodes = this.crypto.generateRecoveryCodes();
    const hashes = recoveryCodes.map((recoveryCode) => this.crypto.hashRecoveryCode(recoveryCode));
    const replaced = this.crypto.isRecoveryCode(code)
      ? await this.repository.replaceRecoveryCodesWithRecoveryCode(userId, this.crypto.hashRecoveryCode(code), hashes)
      : await this.replaceRecoveryCodesWithTotp(userId, authentication.secretEncrypted, code, hashes);

    if (!replaced) {
      throw this.invalidCode();
    }

    return { recoveryCodes };
  }

  private async completeChallenge(
    authentication: {
      secretEncrypted: string;
      recoveryCodeHashes: string[];
    },
    challengeId: string,
    userId: string,
    code: string,
    maxAttempts: number,
  ): Promise<boolean> {
    if (this.crypto.isRecoveryCode(code)) {
      const recoveryCodeHash = this.crypto.hashRecoveryCode(code);

      if (!authentication.recoveryCodeHashes.includes(recoveryCodeHash)) {
        return false;
      }

      return this.repository.completeChallengeWithRecoveryCode(
        challengeId,
        userId,
        recoveryCodeHash,
        authentication.recoveryCodeHashes.filter((hash) => hash !== recoveryCodeHash),
        maxAttempts,
      );
    }

    const secret = this.crypto.decryptSecret(authentication.secretEncrypted);
    const step = this.crypto.findMatchingTotpStep(secret, code);

    return step === null ? false : this.repository.completeChallengeWithTotp(challengeId, userId, step, maxAttempts);
  }

  private async getEnabledAuthentication(userId: string) {
    const authentication = await this.repository.findByUserId(userId);

    if (!authentication?.enabledAt) {
      throw new BadRequestException('Two-factor authentication is not enabled');
    }

    return authentication;
  }

  private async disableWithTotp(userId: string, secretEncrypted: string, code: string): Promise<boolean> {
    const step = this.crypto.findMatchingTotpStep(this.crypto.decryptSecret(secretEncrypted), code);

    return step === null ? false : this.repository.disableWithTotp(userId, step);
  }

  private async replaceRecoveryCodesWithTotp(
    userId: string,
    secretEncrypted: string,
    code: string,
    hashes: string[],
  ): Promise<boolean> {
    const step = this.crypto.findMatchingTotpStep(this.crypto.decryptSecret(secretEncrypted), code);

    return step === null ? false : this.repository.replaceRecoveryCodesWithTotp(userId, step, hashes);
  }

  private invalidCode(): UnauthorizedException {
    return new UnauthorizedException('Invalid or expired two-factor authentication code');
  }

  private get challengeTtlMinutes(): number {
    const configured = Number(process.env.TWO_FACTOR_CHALLENGE_TTL_MINUTES);

    return Number.isFinite(configured) && configured > 0 ? configured : 5;
  }

  private get maxAttempts(): number {
    const configured = Number(process.env.TWO_FACTOR_MAX_ATTEMPTS);

    return Number.isInteger(configured) && configured > 0 ? configured : 5;
  }
}

